import re, json, subprocess
out = subprocess.run(["ffmpeg","-hide_banner","-i","audio/vo.mp3","-af","silencedetect=noise=-32dB:d=0.12","-f","null","-"],capture_output=True,text=True).stderr
P=[]; s=None
for l in out.splitlines():
    m=re.search(r"silence_start: ([\d.]+)",l)
    if m: s=float(m.group(1))
    m=re.search(r"silence_end: ([\d.]+)",l)
    if m and s is not None: P.append((s,float(m.group(1)))); s=None
def w(t): return len(re.findall(r"[ก-ฮA-Za-z0-9]",t))
# paragraphs: (start,end,[(key,text)...])
paras=[
 (0.24,20.56,[("i1","สวัสดีแฟนบอลสิงห์บลูส์ทุกคนครับ กลับมาอัปเดตข่าวเชลซีประจำวันที่ 15 พฤศจิกายน 2026"),("i2","วันนี้มีทั้งข่าวดีระดับแชมป์ของทีมหญิง"),("i3","ผลงานนักเตะเราในเบรกทีมชาติ"),("i4","และประเด็นร้อนในตลาดนักเตะที่ ชาบี อลอนโซ ต้องตัดสินใจก่อนตลาดหน้าหนาวเปิด ไปลุยกันเลยครับ")]),
 (21.51,51.42,[("w1","ประเด็นแรกเป็นไฮไลท์ใหญ่เมื่อคืนที่ผ่านมา ทีมหญิงเชลซีเปิดบ้านสแตมฟอร์ด บริดจ์ รับมือจ่าฝูงอย่างแมนเชสเตอร์ ซิตี้"),("w2","เกมนี้สู้กันสนุกมาก ก่อนที่ช่วงทดเจ็บครึ่งแรก"),("w3","นาทีที่ 45+4 แซนดี บัลติมอร์ จะซัดประตูชัยสุดสวยให้เชลซีนำ 1-0"),("w4","และในนาทีที่ 75 ซิตี้เหลือ 10 คน หลังผู้รักษาประตู อายากะ ยามาชิตะ โดนใบแดง"),("w5","จบเกมเชลซีชนะ 1-0 ยัดความแพ้นัดแรกในลีกให้แชมป์เก่า และแซงขึ้นจ่าฝูง ดับเบิลยูเอสแอล นำซิตี้ 1 คะแนน")]),
 (53.36,68.94,[("w6","แต่ก็มีเรื่องให้กังวลเล็กน้อยครับ คาเดชา บูคานัน เจ็บจากอาการกระทบกระเทือนศีรษะ ต้องเปลี่ยนตัวออกตั้งแต่นาทีที่ 12"),("w7","ส่วน เมลวีน มาลาร์ด เจ็บแฮมสตริงออกในนาทีที่ 35"),("w8","โซเนีย บอมปาสเตอร์ จะเช็กอาการทั้งคู่อีกครั้ง ก่อนเกมหนักกับ เปแอสเช ในแชมเปียนส์ลีกคืนวันพุธนี้")]),
 (69.77,90.94,[("n1","มาดูฝั่งเบรกทีมชาติของทีมชายกันบ้างครับ เมื่อคืน เปโดร เนโต ออกสตาร์ตให้โปรตุเกส แต่พ่ายเดนมาร์ก 1-4 ในเนชันส์ ลีก"),("n2","ส่วน เจโอวานี เควนดา และ ฟิลิป ยอร์เกนเซน เป็นตัวสำรองไม่ได้ลงสนาม"),("n3","ด้าน เอสเตเวา วิลเลียน ลงตัวจริงให้บราซิลในเกมอุ่นเครื่องที่สิงคโปร์ มีโอกาสยิงเกือบเข้าแต่ติดเซฟ ก่อนบราซิลจะแพ้ญี่ปุ่น 2-3")]),
 (91.87,117.71,[("n4","ข่าวดีอยู่ที่ชุดเยาวชนครับ ชิซาราม เอเซนวาทา ยิงจุดโทษช่วยอังกฤษ U19 ชนะเบลารุส 5-0 โดยมีดาวรุ่งเชลซีอย่าง เบอร์นัล เอเมนาโล และ วอลช์ ลงตัวจริงครบ"),("n5","คืนวันอาทิตย์ยังมีเกมให้ตามเชียร์ต่อ มอร์แกน โรเจอร์ส ช่วยอังกฤษเจอสเปน มาโล กุสโต กับฝรั่งเศสพบตุรกี และเบลเยียมของ ลาเวีย กับ เพนเดอร์ส เจออิตาลีของ ปาเลสตรา")]),
 (118.90,135.45,[("t1","ปิดท้ายด้วยประเด็นตลาดนักเตะ Sky Sports News รายงานว่า มาโล กุสโต กำลังทบทวนอนาคตก่อนตลาดเดือนมกราคม"),("t2","เพราะไม่ได้ลงตัวจริงในพรีเมียร์ลีกมา 2 เดือนเต็ม"),("t3","แม้ รีซ เจมส์ จะบาดเจ็บ แต่ ชาบี อลอนโซ เลือกใช้ จอช อาเชียมปง และ มาร์โก ปาเลสตรา มากกว่า")]),
 (136.35,161.37,[("t4","ซิเนอดีน ซีดาน กุนซือทีมชาติฝรั่งเศส เพิ่งออกมาปกป้องกุสโตหลังโดนวิจารณ์ในเกมแพ้อิตาลี"),("t5","มุมมองของผมคือ ถ้ากุสโตยังไม่ได้โอกาสหลังเบรกทีมชาติ โอกาสย้ายออกเดือนมกราคมเปิดกว้างมาก"),("t6","ขณะเดียวกัน The Hard Tackle รายงานว่าเชลซีเปิดเจรจาแข่งกับแมนฯ ยู เพื่อคว้า มาร์ติน บาตูรินา เพลย์เมกเกอร์จากเซเรีย อา ค่าตัวประเมินราว 80 ล้านยูโร")]),
 (162.32,179.20,[("c1","ทั้งหมดนี้คือสรุปข่าวเชลซีประจำวันนี้ครับ"),("c2","เพื่อน ๆ คิดว่าเชลซีควรเก็บ มาโล กุสโต ไว้สู้ต่อ หรือขายแล้วไปเสริมตำแหน่งอื่นดี คอมเมนต์มาแลกเปลี่ยนกันได้เลย"),("c3","อย่าลืมกดไลก์และกดติดตาม จะได้ไม่พลาดข่าวเชลซีทุกเช้า เจอกันใหม่คลิปหน้าครับ")]),
]
gaps=[(a+b)/2 for a,b in P if b-a>=0.2 and 0.5<a<178]
res={}
for a,b,sc in paras:
    tot=sum(w(t) for _,t in sc); acc=0
    for i,(k,t) in enumerate(sc):
        if i==0: res[k]=a
        else:
            est=a+(b-a)*acc/tot
            cand=[g for g in gaps if abs(g-est)<=1.3 and a<g<b]
            res[k]=min(cand,key=lambda g:abs(g-est)) if cand else est
        acc+=w(t)
json.dump({k:round(v,2) for k,v in res.items()},open("tools/bounds.json","w"),indent=1)
print({k:round(v,2) for k,v in res.items()})
